sys_variable_value.value:
// ATF-CP-UI-02: Product Catalog UI
await sn_atf.navigate('/x_2056099_indust_0_customer_portal.do#catalog');
var heading = await screen.findByText('Product Catalog', { exact: false }, { timeout: 15000 });
await waitFor(function() { expect(heading).toBeVisible(); });
var searchInput = await screen.findByPlaceholderText(/search products/i);
expect(searchInput).toBeVisible();
await sn_atf.delay(2000);
var viewBtns = await screen.findAllByText('View Details', { exact: true });
expect(viewBtns.length).toBeGreaterThan(0);
await user.click(viewBtns[0]);
await sn_atf.delay(2000);
var backBtn = await screen.findByText(/Back to Catalog/i, {}, { timeout: 10000 });
expect(backBtn).toBeVisible();
var pricingEl = await screen.queryByText('Pricing');
if (pricingEl) expect(pricingEl).toBeVisible();
var unitPriceEl = await screen.queryByText('Unit Price');
if (unitPriceEl) expect(unitPriceEl).toBeVisible();
var uomEl = await screen.queryByText('UOM');
if (uomEl) expect(uomEl).toBeVisible();
var addCartBtn = await screen.findByText('Add to Cart', { exact: true });
expect(addCartBtn).toBeVisible();
